-- Migration 016: Beute mit Erzähltext, Mine überarbeitet (Bruns Schicksal, Beute aus der Geschichte), Brett-Beute an Entscheidungen gekoppelt,
-- eigenes KI-Abenteuer (Rahmen: Anreise, während der die KI die Geschichte schreibt; Prüfung und Einbau über die Edge-Funktion quest-weaver).

create or replace function public.q_apply(p_run_id bigint, f jsonb) returns text language plpgsql security definer set search_path = public as $$
declare r quest_runs; k text; v text; out text := ''; arm record; ctx jsonb; nid bigint; gst int; lt json; n int;
begin
  if f is null or f = '{}'::jsonb then return ''; end if;
  select * into r from quest_runs where id = p_run_id for update; ctx := q_ctx(r);
  perform q_apply_roles(r, f);
  if f ? 'flag' then update quest_runs set flags = flags || (select jsonb_object_agg(x, true) from jsonb_array_elements_text(f->'flag') x) where id = r.id; end if;
  if f ? 'item_plus' then for k, v in select * from jsonb_each_text(f->'item_plus') loop
    insert into player_items (player_id, item_id, menge) values (r.player_id, k, v::int) on conflict (player_id, item_id) do update set menge = player_items.menge + excluded.menge;
    out := out || ' Erhalten: ' || (select name from items where id = k) || case when v::int > 1 then ' ×' || v else '' end || '.'; end loop; end if;
  if f ? 'item_minus' then for k, v in select * from jsonb_each_text(f->'item_minus') loop update player_items set menge = greatest(0, menge - v::int) where player_id = r.player_id and item_id = k; end loop; end if;
  if f ? 'holz' then update villages set wood_stock = greatest(0, village_wood(villages) + (f->>'holz')::numeric), stock_updated_at = now() where owner_id = r.player_id; out := out || ' Holz ' || (f->>'holz') || '.'; end if;
  if (f ? 'begleiter_sym' or f ? 'begleiter_loy') and coalesce(array_length(r.begleiter, 1), 0) > 0 then
    foreach nid in array r.begleiter loop
      insert into npc_relations (npc_id, player_id, sympathy, loyalty) values (nid, r.player_id, 0, 0) on conflict do nothing;
      update npc_relations set sympathy = greatest(-100, least(100, sympathy + coalesce((f->>'begleiter_sym')::int, 0))), loyalty = greatest(0, least(100, loyalty + coalesce((f->>'begleiter_loy')::int, 0))), updated_at = now() where npc_id = nid and player_id = r.player_id;
    end loop; end if;
  if f ? 'notiz' and coalesce(array_length(r.begleiter, 1), 0) > 0 then
    insert into player_notes (player_id, npc_id, kind, text) values (r.player_id, r.begleiter[1], 'begegnung', left(q_fill(f->>'notiz', ctx), 500));
    insert into npc_memories (npc_id, player_id, kind, text, sympathy_delta) values (r.begleiter[1], r.player_id, 'gespraech', 'Wir haben zusammen ein Abenteuer erlebt. ' || q_fill(f->>'notiz', ctx), 0);
  end if;
  if f ? 'chronik' then insert into chronicle (player_id, key, text) values (r.player_id, f->'chronik'->>0, q_fill(f->'chronik'->>1, ctx)) on conflict do nothing; end if;
  if f ? 'journal' then insert into player_journal (player_id, kind, key, title, text) values (r.player_id, 'auftrag', f->'journal'->>0, f->'journal'->>1, f->'journal'->>2) on conflict do nothing; out := out || ' Tagebuch: ' || (f->'journal'->>1) || '.'; end if;
  if f ? 'begleiter_ab' and coalesce(array_length(r.begleiter, 1), 0) > 0 then update quest_runs set begleiter = begleiter[2:] where id = r.id; end if;
  if f ? 'gefahr' then
    gst := case when jsonb_typeof(f->'gefahr') = 'number' then (f->>'gefahr')::int else 1 end;
    select e.src, e.ref, e.schutz, e.unverwuestlich, coalesce(g.name, i.name) as name into arm
      from p_equipment(r.player_id) e left join player_gear g on e.src = 'gear' and g.id::text = e.ref left join items i on e.src = 'item' and i.id = e.ref
      where e.art = 'ruestung' and e.schutz > 0 order by e.schutz desc limit 1;
    if arm.name is not null and arm.schutz >= gst then
      out := out || ' Deine Rüstung (' || arm.name || ') fängt das Schlimmste ab.';
      if arm.src = 'gear' and not arm.unverwuestlich then
        update player_gear set zustand = greatest(0, zustand - 20) where id = arm.ref::bigint returning zustand into n;
        if n = 0 then out := out || ' Es ist jetzt beschädigt und schützt nicht mehr, bis es repariert wird.'; end if;
      end if;
    else
      update profiles set zustand = 'verletzt', zustand_bis = now() + interval '6 hours' where id = r.player_id;
      out := out || case when arm.name is not null then ' Selbst deine Rüstung (' || arm.name || ') hilft hier nicht.' else '' end || ' Du bist verletzt (Proben −2 für einige Stunden).';
    end if;
  end if;
  if f ? 'beute' and random() < coalesce((f->'beute'->>'chance')::numeric, 1) then
    lt := loot_roll(r.player_id, coalesce((f->'beute'->>'stufe')::int, 1), f->'beute'->>'art', (select titel from quest_templates where id = r.quest_id));
    out := out || coalesce(' ' || q_fill(f->'beute'->>'text', ctx), '') || ' Gefunden: ' || (lt->>'name') || ' (' || (lt->>'stufe') || ').';
    update quest_runs set letztes = coalesce(letztes, '{}'::jsonb) || jsonb_build_object('beute', lt) where id = r.id;
  end if;
  return trim(out);
end;
$$;

-- Wahl treffen: Glücksbringer (einmal neu würfeln) und "erster Versuch sicher"

create or replace function public.quest_board() returns json language plpgsql security definer set search_path = public as $$
declare d date := berlin_day(); sl text; st int; t quest_templates; rol jsonb;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  foreach sl in array array['einfach','mittel','schwer'] loop
    continue when exists (select 1 from quest_offers where player_id = auth.uid() and tag = d and slot = sl);
    st := case sl when 'einfach' then 1 when 'mittel' then 2 else 3 end;
    for t in select q.* from quest_templates q where q.art = 'brett' and q.schwierigkeit = st
      order by (select count(*) from quest_offers o where o.player_id = auth.uid() and o.template_id = q.id and o.tag > d - 7), random() loop
      rol := q_cast(auth.uid(), t.rollen);
      if rol is not null then insert into quest_offers (player_id, tag, slot, template_id, rollen) values (auth.uid(), d, sl, t.id, rol) on conflict do nothing; exit; end if;
    end loop;
  end loop;
  return json_build_object('tag', d, 'neu_ab', berlin_midnight(),
    'angebote', (select coalesce(json_agg(json_build_object('id', o.id, 'slot', o.slot, 'status', o.status, 'run', o.run_id, 'ziel', o.ziel,
        'titel', coalesce(tp.titel, 'Eigenes Abenteuer'), 'schwierigkeit', tp.schwierigkeit,
        'kurz', q_fill(coalesce(tp.kurz, o.ziel, ''), (select coalesce(jsonb_object_agg(key, value->>'name'), '{}'::jsonb) from jsonb_each(o.rollen))),
        'rollen', (select coalesce(json_agg(json_build_object('rolle', tp.rollen->>key, 'id', (value->>'id')::bigint, 'name', value->>'name', 'beruf', value->>'beruf')), '[]'::json) from jsonb_each(o.rollen) where value ? 'id'))
      order by array_position(array['einfach','mittel','schwer','individuell'], o.slot)), '[]'::json)
      from quest_offers o left join quest_templates tp on tp.id = o.template_id where o.player_id = auth.uid() and o.tag = d)
  );
end;
$$;

update public.quest_templates set def = $q${"start":"aufbruch","szenen":{"aufbruch":{"ort":"dorf","text":"Früh am Morgen stehst du {mit} am Dorfrand. Über dem Wasserfall hängt Nebel. Irgendwo dort oben, am alten Pass, soll die verlassene Mine liegen. Welchen Weg nimmst du?","optionen":[{"text":"Den Wildwechsel hinter der zweiten Bachbiegung nehmen","tag":"[Tagebuch: Pfad zur Mine]","wenn":{"wissen":"mine_pfad"},"weiter":"reise_pfad"},{"text":"Durch den Wald einen eigenen Weg suchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":12},"erfolg":{"text":"Du findest alte Kerben an den Bäumen – Wegzeichen der Bergleute.","weiter":"reise_wald"},"misserfolg":{"text":"Das Unterholz wird dichter. Ihr verliert Zeit und Kraft.","folgen":{"flag":["erschoepft"]},"weiter":"reise_umweg"}},{"text":"Den alten Karrenweg nehmen – länger, aber breit und offen","weiter":"reise_karren"}]},"reise_pfad":{"ort":"wald","text":"Ihr folgt dem Wildwechsel bergauf. Moos dämpft eure Schritte, der Wasserfall rauscht immer leiser.","reise":{"minuten":1,"weiter":"eingang","begegnung":{"chance":0.35,"szenen":["b_wanderer","b_wolf"]}}},"reise_wald":{"ort":"wald","text":"Von Kerbe zu Kerbe geht es durch den Nadelwald. Harzgeruch, das Knacken von Ästen.","reise":{"minuten":2,"weiter":"eingang","begegnung":{"chance":0.5,"szenen":["b_wanderer","b_wolf","b_haendler"]}}},"reise_umweg":{"ort":"wald","text":"Dornen, Geröll, ein Bach, den ihr zweimal überquert. Es dauert.","reise":{"minuten":3,"weiter":"eingang","begegnung":{"chance":0.6,"szenen":["b_wanderer","b_wolf"]}}},"reise_karren":{"ort":"wald","text":"Der alte Karrenweg windet sich in Kehren den Hang hinauf. Hier sind früher Erzwagen gefahren.","reise":{"minuten":2,"weiter":"eingang","begegnung":{"chance":0.7,"szenen":["b_haendler","b_wanderer"]}}},"b_wanderer":{"ort":"wald","text":"Am Wegrand sitzt ein Mann mit blutigem Bein. Ein Wanderer aus dem Süden, sagt er – gestürzt am Geröllhang. Er ist blass.","optionen":[{"text":"Die Wunde versorgen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":11},"erfolg":{"text":"Du reinigst und verbindest die Wunde. Er atmet auf. „Ich heiße Arvid. Das vergesse ich dir nicht.“ Dann flüstert er: „Im Stollen da oben brennt Licht. Jemand ist dort.“","folgen":{"flag":["licht_im_stollen"],"begleiter_sym":2,"chronik":["arvid_gerettet","Ich habe Arvid, einem verletzten Wanderer, auf dem Weg zur Mine das Bein verbunden."]},"weiter":"eingang"},"misserfolg":{"text":"Du tust, was du kannst. Es reicht, damit er sich ins Tal schleppen kann. „Danke. Im Stollen ist jemand – sei vorsichtig.“","folgen":{"flag":["licht_im_stollen"],"chronik":["arvid_geholfen","Ich habe einem verletzten Wanderer namens Arvid geholfen, so gut ich konnte."]},"weiter":"eingang"}},{"text":"Ihm Brot und Wasser geben und weiterziehen","weiter":"eingang","ergebnis":"Er nickt dankbar. „Im Stollen ist jemand“, murmelt er noch. „Sei vorsichtig.“","folgen":{"flag":["licht_im_stollen"],"chronik":["arvid_geholfen","Ich habe einem verletzten Wanderer namens Arvid Brot und Wasser gegeben."]}},{"text":"{bb} soll ihn ins Dorf bringen","tag":"[{bb}]","wenn":{"begleiter":true},"weiter":"eingang","ergebnis":"{bb} nickt ernst und stützt den Mann. „Geh du weiter. Ich bringe ihn heim.“ Den Rest des Weges bist du ohne {bb} unterwegs.","folgen":{"begleiter_sym":4,"begleiter_ab":true,"chronik":["arvid_heimgebracht","Auf dem Weg zur Mine haben wir einen verletzten Wanderer gefunden und ins Dorf bringen lassen."]}},{"text":"Weitergehen. Du hast keine Zeit.","weiter":"eingang","ergebnis":"Sein Blick folgt dir noch lange.","folgen":{"begleiter_sym":-3,"chronik":["arvid_zurueckgelassen","Ich habe auf dem Weg zur Mine einen verletzten Wanderer zurückgelassen."]}}]},"b_wolf":{"ort":"wald","text":"Zwischen den Stämmen ein graues Fell. Ein Wolf, mager, mit gesenktem Kopf – und er ist nicht allein.","optionen":[{"text":"Einen Warnpfeil vor ihre Pfoten schießen","tag":"[Bogen]","wenn":{"item":"bogen"},"probe":{"id":"flink","dc":10},"erfolg":{"text":"Der Pfeil zischt in den Boden. Die Wölfe weichen zurück und verschwinden.","weiter":"eingang"},"misserfolg":{"text":"Der Pfeil geht weit daneben – die Wölfe kommen näher!","weiter":"b_wolf_angriff"}},{"text":"Groß machen, brüllen, den Stock schwingen","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Die Wölfe ziehen sich knurrend zurück.","weiter":"eingang"},"misserfolg":{"text":"Sie lassen sich nicht beeindrucken.","weiter":"b_wolf_angriff"}},{"text":"{bb} kennt die Tiere – lass {bb} machen","tag":"[{bb}]","wenn":{"begleiter_beruf":["Jäger","Jägerin","Falknerin","Hirte"]},"weiter":"eingang","ergebnis":"{bb} hebt langsam die Hand, spricht leise und weicht Schritt für Schritt zurück. Die Wölfe verlieren das Interesse. „Hungrig, nicht böse“, sagt {bb}.","folgen":{"begleiter_sym":3,"begleiter_loy":1}},{"text":"Leise gegen den Wind ausweichen","tag":"[Schleichen]","probe":{"id":"flink","dc":12},"erfolg":{"text":"Ihr schleicht in weitem Bogen vorbei. Die Wölfe bemerken euch nicht.","weiter":"eingang"},"misserfolg":{"text":"Ein Ast bricht. Köpfe fahren herum.","weiter":"b_wolf_angriff"}}]},"b_wolf_angriff":{"ort":"wald","gefahr":true,"text":"Ein Wolf springt!","optionen":[{"text":"Den Wolf abwehren","tag":"[Anpacken]","probe":{"id":"anpacken","dc":12},"erfolg":{"text":"Du stößt ihn zurück. Das Rudel flieht in den Wald.","weiter":"eingang"},"misserfolg":{"text":"Zähne schlagen zu, dann ist der Spuk vorbei.","folgen":{"gefahr":true},"weiter":"eingang"}},{"text":"Auf einen Felsen springen","tag":"[Flink]","probe":{"id":"flink","dc":11},"erfolg":{"text":"Mit einem Satz bist du oben. Die Wölfe umkreisen den Felsen und ziehen ab.","weiter":"eingang"},"misserfolg":{"text":"Du rutschst ab und schlägst hart auf.","folgen":{"gefahr":true},"weiter":"eingang"}}]},"b_haendler":{"ort":"wald","text":"Ein Händler mit Maultier kommt euch entgegen. „Zur Mine? Mutig. Ich hätte da eine Laterne – für etwas Holz.“","optionen":[{"text":"Die Laterne für 15 Holz kaufen","wenn":{"nicht_item":"laterne","holz":15},"weiter":"eingang","ergebnis":"Er grinst. „Gute Wahl. Da unten ist es finster.“","folgen":{"holz":-15,"item_plus":{"laterne":1}}},{"text":"Den Preis drücken","tag":"[Feilschen]","wenn":{"nicht_item":"laterne","holz":8},"probe":{"id":"feilschen","dc":12},"erfolg":{"text":"„Acht Holz, und du erzählst keinem davon.“ Abgemacht.","folgen":{"holz":-8,"item_plus":{"laterne":1}},"weiter":"eingang"},"misserfolg":{"text":"Er bleibt hart. „Fünfzehn, mein Freund.“ Du lässt es.","weiter":"eingang"}},{"text":"Nach der Mine fragen","weiter":"eingang","ergebnis":"„Da treibt sich ein Bergmann herum. Brun heißt er, aus Erzklamm. Hat eine kranke Tochter.“","folgen":{"flag":["brun_bekannt"]}},{"text":"Grüßen und weitergehen","weiter":"eingang"}]},"eingang":{"ort":"mine","text":"Der Eingang ist halb verschüttet, die Holzstützen sind morsch. Aus der Tiefe weht kalter Wind.","optionen":[{"text":"{bb} soll die Stützen prüfen","tag":"[{bb}]","wenn":{"begleiter_beruf":["Zimmermann","Steinmetz","Bergmann","Holzfäller","Schmied"],"nicht_flag":"gesichert"},"weiter":"eingang","ergebnis":"{bb} klopft jeden Balken ab und keilt zwei lockere Stützen fest. „Jetzt hält es. Hoffentlich.“","folgen":{"flag":["gesichert"],"begleiter_sym":2}},{"text":"Die Laterne anzünden und hinein","wenn":{"item":"laterne"},"weiter":"stollen","folgen":{"flag":["licht"]}},{"text":"Eine Fackel aus Harz und Kienspan machen","tag":"[Spuren lesen]","wenn":{"nicht_item":"laterne"},"probe":{"id":"spuren","dc":10},"erfolg":{"text":"Die Fackel knistert und wirft tanzende Schatten.","folgen":{"flag":["licht"]},"weiter":"stollen"},"misserfolg":{"text":"Das Harz will nicht brennen. Ihr müsst im Halbdunkel gehen.","folgen":{"flag":["dunkel"]},"weiter":"stollen"}},{"text":"Ohne Licht hinein","weiter":"stollen","folgen":{"flag":["dunkel"]}}]},"stollen":{"ort":"stollen","text":"Ihr tastet euch tiefer. An einer Abzweigung: frische Kratzspuren und ein Geräusch wie Metall auf Stein. Jemand ist hier.","optionen":[{"text":"Erst den Seitengang absuchen – die alten Bergleute haben hier gelagert","tag":"[Spuren lesen]","wenn":{"nicht_flag":"gesucht"},"probe":{"id":"spuren","dc":12,"mod":{"dunkel":2}},"erfolg":{"text":"Hinter eingestürzten Brettern steht eine verrottete Kiste. Darin, in geöltes Tuch gewickelt, liegt etwas, das die Jahre überstanden hat.","folgen":{"flag":["gesucht"],"beute":{"stufe":2,"chance":1,"text":"Was die Bergleute hier zurückgelassen haben, gehört jetzt dir."}},"weiter":"stollen"},"misserfolg":{"text":"Nur Schutt und Rattenkot. Und das Hämmern weiter vorne ist verstummt.","folgen":{"flag":["gesucht"]},"weiter":"ueberrascht"}},{"text":"Leise näherschleichen","tag":"[Schleichen]","probe":{"id":"flink","dc":12,"mod":{"dunkel":2}},"erfolg":{"text":"Du schleichst bis an einen Felsvorsprung und hörst einen Mann murmeln: „… nur noch ein Stück, dann reicht es für die Medizin, Lene …“","folgen":{"flag":["belauscht"]},"weiter":"fremder"},"misserfolg":{"text":"Ein Stein knirscht unter deinem Fuß. Das Hämmern verstummt.","weiter":"ueberrascht"}},{"text":"Lauschen und abwarten","tag":"[Sinne]","probe":{"id":"spuren","dc":13,"mod":{"dunkel":2}},"erfolg":{"text":"Ein Mann, allein, erschöpft. Er spricht mit sich selbst – von einer kranken Tochter.","folgen":{"flag":["belauscht"]},"weiter":"fremder"},"misserfolg":{"text":"Plötzlich ist es still. Zu still.","weiter":"ueberrascht"}},{"text":"Laut rufen: „Wer ist da?“","weiter":"fremder"}]},"ueberrascht":{"ort":"stollen","gefahr":true,"text":"Aus der Dunkelheit stürzt ein Mann mit erhobener Spitzhacke auf dich zu!","optionen":[{"text":"Ausweichen","tag":"[Flink]","probe":{"id":"flink","dc":12},"erfolg":{"text":"Die Hacke kracht neben dir in den Fels. „Halt!“, rufst du – der Mann erstarrt.","weiter":"fremder"},"misserfolg":{"text":"Der Stiel trifft dich, bevor er erkennt, dass du kein Räuber bist.","folgen":{"gefahr":true},"weiter":"fremder"}},{"text":"{bb} stellt sich dazwischen","tag":"[{bb}]","wenn":{"begleiter":true},"weiter":"fremder","ergebnis":"{bb} packt den Stiel der Hacke. Einen Moment ringen beide – dann lässt der Mann los.","folgen":{"begleiter_loy":2,"begleiter_sym":2}},{"text":"Die Klinge ziehen","tag":"[Waffe]","wenn":{"item_eines":["schwert","dolch"]},"weiter":"fremder","ergebnis":"Im Licht blitzt Stahl. Der Mann lässt die Hacke sinken."}]},"fremder":{"ort":"stollen","text":"Ein abgemagerter Mann mit Staub im Bart. „Brun“, sagt er. „Bergmann aus Erzklamm. Seit dort die Mine eingestürzt ist, gibt es keine Arbeit. Hier unten glänzt es nach Silber. Meine Tochter ist krank – ohne Silber keine Medizin.“","optionen":[{"text":"Lügt er?","tag":"[Menschenkenntnis]","wenn":{"nicht_flag":"geprueft"},"probe":{"id":"menschenkenntnis","dc":12},"erfolg":{"text":"Seine Hände zittern, sein Blick nicht. Er sagt die Wahrheit.","folgen":{"flag":["geprueft","wahrheit"]},"weiter":"fremder"},"misserfolg":{"text":"Du wirst nicht schlau aus ihm.","folgen":{"flag":["geprueft"]},"weiter":"fremder"}},{"text":"Schweigen und ihn weiterschürfen lassen","weiter":"einsturz","ergebnis":"Brun sieht dich lange an. „Danke.“ Das Hämmern setzt wieder ein.","folgen":{"flag":["brun_ok"],"chronik":["brun_gedeckt","Ich habe Brun heimlich in der Mine schürfen lassen."]}},{"text":"Das Silber teilen – halb für ihn, halb für das Dorf","weiter":"einsturz","ergebnis":"Ihr schlagt gemeinsam Erz aus der Wand. Brun lacht zum ersten Mal.","folgen":{"flag":["brun_ok"],"item_plus":{"silbererz":1},"begleiter_sym":1,"chronik":["brun_geteilt","Ich habe mit Brun das Silber in der Mine geteilt."]}},{"text":"„Komm mit ins Dorf. Wir brauchen Bergleute – und für deine Tochter finden wir Hilfe.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":12,"mod":{"belauscht":-2,"wahrheit":-1}},"erfolg":{"text":"Brun schluckt. „Du meinst das ernst?“ Er nickt langsam. „Ich hole Lene. Dann kommen wir.“","folgen":{"flag":["brun_ok"],"begleiter_sym":2,"chronik":["brun_eingeladen","Ich habe Brun und seine kranke Tochter Lene in unser Dorf eingeladen."],"journal":["brun_kommt","Brun will kommen","Der Bergmann Brun will mit seiner kranken Tochter Lene in unser Dorf ziehen. Er kennt die Mine wie kein anderer."]},"weiter":"einsturz"},"misserfolg":{"text":"„Schöne Worte“, sagt Brun. „Die hab ich schon oft gehört.“","folgen":{"flag":["brun_ok"]},"weiter":"einsturz"}},{"text":"„Verschwinde. Die Mine gehört unserem Dorf.“","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":11},"erfolg":{"text":"Brun weicht zurück, rafft seinen Beutel und geht. Ein paar Brocken Erz bleiben liegen.","folgen":{"flag":["brun_weg"],"item_plus":{"silbererz":2},"begleiter_sym":-2,"chronik":["brun_vertrieben","Ich habe Brun aus der Mine gejagt, obwohl seine Tochter krank ist."]},"weiter":"einsturz"},"misserfolg":{"text":"Brun spuckt aus. „Versuch’s doch.“ Im selben Moment bebt der Boden.","folgen":{"flag":["brun_feind"],"chronik":["brun_feind","Brun, der Bergmann aus Erzklamm, ist nicht gut auf mich zu sprechen."]},"weiter":"einsturz"}}]},"einsturz":{"ort":"stollen","gefahr":true,"text":"Ein dumpfes Grollen. Staub rieselt aus der Decke – dann kracht ein Balken. Der Stollen bricht ein!","optionen":[{"text":"Alle zum Ausgang!","tag":"[Flink]","probe":{"id":"flink","dc":13,"mod":{"gesichert":-3,"dunkel":2,"erschoepft":2}},"erfolg":{"text":"Ihr stürzt ins Freie, hinter euch donnern die Felsen.","folgen":{"begleiter_loy":2},"weiter":"nach_einsturz"},"misserfolg":{"text":"Ein Brocken trifft dich an der Schulter, aber du kommst raus.","folgen":{"gefahr":true},"weiter":"nach_einsturz"}},{"text":"{bb} soll die Decke abstützen","tag":"[{bb}]","wenn":{"begleiter_beruf":["Zimmermann","Steinmetz","Bergmann","Holzfäller","Schmied","Bauer","Wache","Söldnerin","Hauptmann"]},"probe":{"id":"anpacken","dc":11,"mod":{"gesichert":-3}},"erfolg":{"text":"{bb} stemmt sich gegen den Balken. „Lauft!“ Ihr schafft es – {bb} zuletzt, mit einem schiefen Grinsen.","folgen":{"begleiter_loy":3,"begleiter_sym":4,"chronik":["mine_gerettet","In der Mine hat {bb} uns alle beim Einsturz gerettet."],"notiz":"Beim Einsturz der Mine hat {bb} die Decke gehalten, bis wir draußen waren. Das vergesse ich nicht."},"weiter":"nach_einsturz"},"misserfolg":{"text":"Der Balken gibt nach. Ihr kommt raus, aber nicht ohne Blessuren.","folgen":{"gefahr":true,"begleiter_loy":1},"weiter":"nach_einsturz"}},{"text":"Den Balken selbst stemmen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":13,"mod":{"gesichert":-3}},"erfolg":{"text":"Du hältst den Balken, bis alle draußen sind. Dann lässt du los und springst.","folgen":{"begleiter_sym":4,"begleiter_loy":3,"notiz":"In der Mine habe ich die Decke gehalten, bis alle draußen waren."},"weiter":"nach_einsturz"},"misserfolg":{"text":"Der Balken ist zu schwer. Er drückt dich zu Boden, bevor du dich befreist.","folgen":{"gefahr":true},"weiter":"nach_einsturz"}},{"text":"Brun mitreißen","tag":"[Flink]","wenn":{"flag":"brun_ok"},"probe":{"id":"flink","dc":12,"mod":{"gesichert":-2}},"erfolg":{"text":"Du packst Brun am Arm. Gemeinsam stolpert ihr ins Licht.","folgen":{"flag":["brun_gerettet"],"chronik":["brun_gerettet","Ich habe Brun beim Einsturz der Mine das Leben gerettet."]},"weiter":"nach_einsturz"},"misserfolg":{"text":"Ihr kommt beide raus – du mit einer blutenden Stirn.","folgen":{"flag":["brun_gerettet"],"gefahr":true,"chronik":["brun_gerettet","Ich habe Brun beim Einsturz der Mine das Leben gerettet."]},"weiter":"nach_einsturz"}}]},"nach_einsturz":{"ort":"mine","text":"Draußen legt sich der Staub. Ihr hustet, blinzelt ins Licht, zählt durch – alle da. Und Brun?","optionen":[{"text":"Zu Brun gehen","wenn":{"flag":"brun_gerettet"},"weiter":"draussen","ergebnis":"Brun sitzt auf einem Stein, Staub im Bart, und starrt auf den verschütteten Eingang. Dann nestelt er etwas aus seinem Hemd. „Das wollte ich für Lenes Medizin verkaufen. Aber ohne dich läge ich jetzt da drin.“ Er drückt es dir in die Hand und schließt deine Finger darum. „Ich finde einen anderen Weg. Versprochen.“","folgen":{"beute":{"stufe":2,"chance":1,"art":"talisman","text":"Bruns Geschenk:"},"chronik":["brun_dank","Brun hat mir nach dem Einsturz etwas geschenkt, das er eigentlich für die Medizin seiner Tochter verkaufen wollte."],"journal":["brun_tochter","Bruns Tochter Lene","Brun aus Erzklamm braucht Medizin für seine kranke Tochter Lene. Vielleicht kann ich helfen."]}},{"text":"Nach Brun rufen","wenn":{"flag":"brun_ok","nicht_flag":"brun_gerettet"},"weiter":"draussen","ergebnis":"Lange nichts. Dann Husten, ein Fluch – und aus einem schmalen Nebenschacht kriecht Brun, die Stirn blutig, aber lebendig. Er sieht dich an, nickt einmal und humpelt den Hang hinunter Richtung Erzklamm.","folgen":{"chronik":["brun_ueberlebt","Brun hat den Einsturz der Mine überlebt und ist nach Erzklamm zurückgehumpelt."],"journal":["brun_tochter","Bruns Tochter Lene","Brun aus Erzklamm braucht Medizin für seine kranke Tochter Lene."]}},{"text":"Nach Brun sehen","wenn":{"flag":"brun_feind"},"weiter":"draussen","ergebnis":"Von Brun keine Spur. Ob er es durch einen anderen Schacht hinausgeschafft hat oder unter den Felsen liegt, wirst du heute nicht erfahren.","folgen":{"chronik":["brun_verschollen","Seit dem Einsturz der Mine weiß niemand, was aus Brun geworden ist."]}},{"text":"Durchatmen","wenn":{"flag":"brun_weg"},"weiter":"draussen","ergebnis":"Brun war längst fort, als die Decke kam. Vielleicht war das sein Glück. Vielleicht deins."},{"text":"Durchatmen","wenn":{"nicht_flag":"brun_ok"},"weiter":"draussen","ergebnis":"Ihr lebt. Das zählt fürs Erste."}]},"draussen":{"ort":"wald","text":"Draußen. Staub, Sonnenlicht, Vogelgezwitscher. Hinter euch ist der Stollen verschüttet – vorerst. Ihr macht euch auf den Heimweg.","reise":{"minuten":1,"weiter":"lagerfeuer"}},"lagerfeuer":{"ort":"feuer","text":"Am Abend sitzt du {mit} am Feuer am Waldrand. Die Funken steigen in den Nachthimmel.","optionen":[{"text":"„Danke dir, {b1}. Ohne dich hätte ich das nicht geschafft.“","tag":"[{b1}]","wenn":{"begleiter":true},"weiter":"ende","ergebnis":"{b1} schaut ins Feuer. „Für dich doch.“ Es ist ein stilles, gutes Schweigen.","folgen":{"begleiter_sym":5,"begleiter_loy":2,"notiz":"Am Lagerfeuer nach der Mine habe ich {b1} gedankt. Ein guter Moment."}},{"text":"„Erzähl mir etwas, das sonst keiner über dich weiß, {b1}.“","tag":"[{b1}]","wenn":{"begleiter":true},"weiter":"ende","ergebnis":"{b1} zögert. Dann erzählt {b1} leise von früher, von Dingen, über die im Dorf niemand spricht. Zwischen euch ist etwas gewachsen.","folgen":{"begleiter_sym":4,"begleiter_loy":3,"notiz":"Am Lagerfeuer nach der Mine hat sich {b1} mir geöffnet. Ich glaube, wir sind uns nähergekommen."}},{"text":"In die Sterne schauen und an Brun denken","wenn":{"flag":"brun_ok"},"weiter":"ende","ergebnis":"Ob er es nach Hause geschafft hat? Ob seine Tochter gesund wird?"},{"text":"Das Erz im Feuerschein betrachten und Pläne schmieden","wenn":{"item":"silbererz"},"weiter":"ende","ergebnis":"Silber. Wenn dort mehr davon liegt, könnte das Dorf reich werden – oder gierig."},{"text":"Schlafen","weiter":"ende"}]},"ende":{"ort":"feuer","ende":true,"text":"Die verlassene Mine – vorerst abgeschlossen. Was du dort getan hast, wird man sich erzählen.","folgen":{"chronik":["mine_besucht","Ich war in der verlassenen Mine am alten Pass."]}}}}$q$::jsonb where id = 'mine';

insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def)
select e->>'id', e->>'titel', e->>'kurz', e->>'kurz', 'brett', (e->>'schwierigkeit')::int, e->'rollen', e->'def' from jsonb_array_elements($q$[{"id":"b_vorrat","titel":"Der verschwundene Vorrat","kurz":"{A} vermisst einen Sack Saatgut aus dem Vorratsschuppen. Jemand im Dorf muss ihn genommen haben.","schwierigkeit":1,"rollen":{"A":"Bestohlene Person","B":"Verdächtige Person","C":"Zeuge"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} steht vor dem offenen Schuppen, die Hände in die Hüften gestemmt. „Ein ganzer Sack Saatgut. Weg. Ohne den wird mein Feld im Frühjahr kahl bleiben.“","optionen":[{"text":"„Ich finde heraus, wer das war.“","weiter":"spuren"},{"text":"„Beruhig dich erst mal. Wir finden ihn.“","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":10},"erfolg":{"text":"{A} atmet durch. „Du hast recht. Ich hab mich da reingesteigert.“","folgen":{"sym":{"A":2}},"weiter":"spuren"},"misserfolg":{"text":"„Beruhigen? Das ist mein Winter, der da fehlt!“","weiter":"spuren"}}]},"spuren":{"ort":"dorf","text":"Im Staub vor dem Schuppen sind Spuren, und an der Tür hängt ein Faden grober, brauner Wolle.","optionen":[{"text":"Den Spuren folgen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":11},"erfolg":{"text":"Die Spuren führen zum Haus von {B} – und dort, halb unter Stroh versteckt, liegt der Sack.","folgen":{"flag":["beweis"]},"weiter":"entdeckt"},"misserfolg":{"text":"Die Spuren verlieren sich zwischen den Häusern.","weiter":"zeuge"}},{"text":"Herumfragen, wer etwas gesehen hat","weiter":"zeuge"}]},"zeuge":{"ort":"dorf","text":"{C} kratzt sich am Kinn. „Gestern Abend? Da hab ich {B} mit einem Sack über der Schulter gesehen. Hab mir nichts dabei gedacht.“","optionen":[{"text":"Zu {B} gehen","weiter":"entdeckt","folgen":{"merkt":{"C":"Ich habe {held} erzählt, was ich gesehen habe. Hoffentlich war das richtig."}}}]},"entdeckt":{"ort":"dorf","text":"{B} sieht dich kommen und wird blass. „Ich … meine Kinder hatten Hunger. Ich wollte es zurückgeben, sobald ich kann. Bitte sag es nicht {A}.“","optionen":[{"text":"Lügt {B}?","tag":"[Menschenkenntnis]","wenn":{"nicht_flag":"geprueft"},"probe":{"id":"menschenkenntnis","dc":11},"erfolg":{"text":"Die Angst ist echt. In der Küche steht ein leerer Topf.","folgen":{"flag":["geprueft","wahrheit"]},"weiter":"entdeckt"},"misserfolg":{"text":"Du kannst es nicht sagen.","folgen":{"flag":["geprueft"]},"weiter":"entdeckt"}},{"text":"Den Sack zurückbringen und {A} die Wahrheit sagen","weiter":"ende_wahrheit","ergebnis":"{A} nimmt den Sack schweigend entgegen. Dann geht {A} hinüber zu {B}. Was die beiden reden, hörst du nicht.","folgen":{"sym":{"A":4,"B":-4},"merkt":{"A":"{held} hat mein Saatgut gefunden und mir die Wahrheit über {B} gesagt.","B":"{held} hat mich verraten, obwohl ich gefleht habe."},"chronik":["brett_vorrat_wahrheit","Ich habe herausgefunden, dass {B} das Saatgut von {A} genommen hat – und es offen gesagt."]}},{"text":"Den Sack heimlich zurücklegen und schweigen","weiter":"ende_still","ergebnis":"In der Nacht stellst du den Sack zurück in den Schuppen. {A} findet ihn am Morgen und hält es für ein Wunder.","folgen":{"sym":{"A":1,"B":6},"merkt":{"B":"{held} hat geschwiegen und mich gerettet. Das vergesse ich nicht."},"chronik":["brett_vorrat_still","Ich habe für {B} geschwiegen und das Saatgut heimlich zurückgebracht."]}},{"text":"„Wir gehen zusammen zu {A}. Du erklärst es selbst.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":12,"mod":{"wahrheit":-2}},"erfolg":{"text":"{B} nickt zitternd. Vor {A} bricht {B} in Tränen aus. {A} schweigt lange – dann bietet {A} an, das Saatgut zu teilen.","folgen":{"sym":{"A":4,"B":4},"merkt":{"A":"{held} hat dafür gesorgt, dass {B} ehrlich zu mir war.","B":"{held} hat mir geholfen, das Richtige zu tun."},"chronik":["brett_vorrat_versoehnt","{A} und {B} haben sich versöhnt – ich habe sie zusammengebracht."]},"weiter":"ende_gut"},"misserfolg":{"text":"{B} schüttelt den Kopf. „Das kann ich nicht.“ Du bringst den Sack allein zurück.","folgen":{"sym":{"A":2,"B":-2}},"weiter":"ende_wahrheit"}}]},"ende_wahrheit":{"ort":"dorf","ende":true,"text":"Das Saatgut ist zurück. Im Dorf wird man darüber reden.","folgen":{"beute":{"stufe":1,"chance":0.6,"text":"Am Abend steht {A} vor deiner Tür und drückt dir zum Dank etwas in die Hand, das lange im Schuppen lag."}}},"ende_still":{"ort":"dorf","ende":true,"text":"Ein Geheimnis mehr, das du trägst. Belohnt wirst du dafür nicht – aber {B} wird es dir nicht vergessen."},"ende_gut":{"ort":"dorf","ende":true,"text":"Manchmal ist ein Streit der Anfang von etwas Besserem.","folgen":{"beute":{"stufe":1,"chance":0.8,"text":"{A} und {B} haben zusammengelegt und schenken dir etwas – als Dank dafür, dass du sie zusammengebracht hast."}}}}}},{"id":"b_brief","titel":"Ein Brief für die Mühle","kurz":"{A} bittet dich, einen versiegelten Brief zur Mühle am Bach zu bringen. Persönlich, sagt {A}, und schnell.","schwierigkeit":1,"rollen":{"A":"Absender","B":"Empfänger"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} drückt dir einen gefalteten Brief mit einem Wachssiegel in die Hand. „Für {B}. Gib ihn niemand anderem. Und … lies ihn nicht.“","optionen":[{"text":"Losgehen","weiter":"weg"}]},"weg":{"ort":"wald","text":"Der Pfad zur Mühle folgt dem Bach. Das Wasser glitzert, irgendwo klopft ein Specht.","reise":{"minuten":1,"weiter":"zweifel","begegnung":{"chance":0.3,"szenen":["b_haendler","b_wanderer"]}}},"b_haendler":{"ort":"wald","text":"Ein Händler hockt am Wegrand und flickt seinen Karren. „Hilf mir kurz, Freund? Das Rad will nicht.“","optionen":[{"text":"Mit anpacken","tag":"[Anpacken]","probe":{"id":"anpacken","dc":10},"erfolg":{"text":"Das Rad sitzt. Der Händler drückt dir zum Dank etwas in die Hand.","folgen":{"beute":{"stufe":1,"chance":1,"text":"„Für deine Mühe“, sagt er und gibt dir etwas aus seinem Karren."}},"weiter":"zweifel"},"misserfolg":{"text":"Ihr flucht beide, aber am Ende hält es irgendwie.","weiter":"zweifel"}},{"text":"Keine Zeit, der Brief eilt","weiter":"zweifel"}]},"b_wanderer":{"ort":"wald","text":"Ein alter Mann sitzt auf einem Stein. „Zur Mühle? Grüß mir das Wasserrad. Wir sind zusammen alt geworden.“ Er lacht leise.","optionen":[{"text":"Ein Stück mit ihm reden","weiter":"zweifel","ergebnis":"Er erzählt von früher, als die Mühle noch drei Räder hatte."}]},"zweifel":{"ort":"wald","text":"Kurz vor der Mühle löst sich das Siegel ein wenig. Man könnte hineinschauen, ohne dass es jemand merkt.","optionen":[{"text":"Hineinschauen","tag":"[Flink]","probe":{"id":"flink","dc":11},"erfolg":{"text":"Du liest: „Ich habe es nie vergessen. Komm zum Fest. Bitte.“ Du klebst das Siegel sauber wieder zu.","folgen":{"flag":["gelesen"]},"weiter":"muehle"},"misserfolg":{"text":"Das Siegel bricht ganz. Jetzt sieht man, dass jemand den Brief geöffnet hat.","folgen":{"flag":["gelesen","siegel_kaputt"]},"weiter":"muehle"}},{"text":"Den Brief ungelesen lassen","weiter":"muehle","folgen":{"flag":["treu"]}}]},"muehle":{"ort":"dorf","text":"{B} wischt sich das Mehl von den Händen und nimmt den Brief. Als {B} den Absender erkennt, wird es still.","optionen":[{"text":"Abwarten","wenn":{"nicht_flag":"siegel_kaputt"},"weiter":"antwort"},{"text":"„Das Siegel war schon kaputt, als …“","tag":"[Überreden]","wenn":{"flag":"siegel_kaputt"},"probe":{"id":"ueberreden","dc":13},"erfolg":{"text":"{B} glaubt dir – oder will dir glauben.","weiter":"antwort"},"misserfolg":{"text":"{B} sieht dich lange an. „Du hast ihn gelesen.“","folgen":{"sym":{"B":-4,"A":-3},"merkt":{"B":"{held} hat meinen Brief gelesen. Neugieriges Volk."}},"weiter":"antwort"}},{"text":"Die Wahrheit sagen: „Ich habe hineingeschaut. Es tut mir leid.“","wenn":{"flag":"gelesen"},"weiter":"antwort","ergebnis":"{B} schnaubt – dann lächelt {B} schief. „Wenigstens ehrlich.“","folgen":{"sym":{"B":1}}}]},"antwort":{"ort":"dorf","text":"{B} schreibt ein paar Zeilen auf die Rückseite und faltet den Brief neu. „Bring ihn zurück. Und sag {A} … nein. Bring ihn einfach.“","optionen":[{"text":"Zurück zu {A}","weiter":"ende","folgen":{"sym":{"A":4,"B":2},"merkt":{"A":"{held} hat meinen Brief zu {B} gebracht – und eine Antwort mitgebracht.","B":"{held} hat mir einen Brief von {A} gebracht. Nach all den Jahren."},"chronik":["brett_brief","Ich habe einen Brief zwischen {A} und {B} getragen. Was darin stand, war wichtig."]}}]},"ende":{"ort":"dorf","ende":true,"text":"{A} liest die Antwort und dreht sich weg, damit du die Augen nicht siehst. „Danke“, sagt {A} leise.","folgen":{"beute":{"stufe":1,"chance":0.6,"text":"Dann holt {A} etwas aus einer alten Truhe. „Nimm. Bei mir liegt es nur herum.“"}}}}}},{"id":"b_grenzstein","titel":"Streit um den Grenzstein","kurz":"{A} und {B} streiten, wem das Stück Land am alten Grenzstein gehört. Das Dorf erwartet, dass jemand entscheidet.","schwierigkeit":2,"rollen":{"A":"Streitpartei","B":"Streitpartei","C":"Älteste Stimme"},"def":{"start":"streit","szenen":{"streit":{"ort":"dorf","text":"Am Feldrand stehen sich {A} und {B} gegenüber. „Der Stein stand immer hier!“ – „Weil du ihn letzten Herbst versetzt hast!“ Ein paar Leute sehen zu.","optionen":[{"text":"Dazwischengehen und beide beruhigen","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":12},"erfolg":{"text":"Die Stimmen werden leiser. Beide sind bereit, dich anzuhören.","folgen":{"flag":["ruhig"]},"weiter":"pruefen"},"misserfolg":{"text":"„Halt dich raus!“, rufen beide gleichzeitig. Immerhin sind sie sich da einig.","weiter":"pruefen"}},{"text":"„Ich sehe mir den Stein an.“","weiter":"pruefen"}]},"pruefen":{"ort":"wald","text":"Der Grenzstein ist alt und bemoost. Am Boden daneben sieht man eine frische Kuhle, als hätte man ihn bewegt – oder als hätten Wildschweine gewühlt.","optionen":[{"text":"Den Boden genau untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":13},"erfolg":{"text":"Die Kuhle stammt von Schweinen. Aber unter dem Moos zeigt eine verwitterte Kerbe in Richtung von {B}s Feld.","folgen":{"flag":["kerbe"]},"weiter":"wissen"},"misserfolg":{"text":"Du wirst nicht schlau daraus.","weiter":"wissen"}},{"text":"Die alten Zeichen auf dem Stein deuten","tag":"[Altes Wissen]","probe":{"id":"altes_wissen","dc":12},"erfolg":{"text":"Das Zeichen ist ein altes Flurmal: Die Grenze verläuft entlang der Kerbe – und die zeigt zu {B}.","folgen":{"flag":["kerbe","gedeutet"]},"weiter":"wissen"},"misserfolg":{"text":"Die Zeichen sind zu verwittert.","weiter":"wissen"}},{"text":"{C} fragen, wie es früher war","weiter":"aelteste"}]},"aelteste":{"ort":"dorf","text":"{C} lehnt sich zurück. „Als ich jung war, hat der Stein weiter drüben gestanden. Aber das ist lange her, und das Gedächtnis ist ein Lügner.“","optionen":[{"text":"Zurück zum Feld","weiter":"wissen","folgen":{"flag":["erinnerung"]}}]},"wissen":{"ort":"dorf","text":"Alle warten auf dein Wort. {A} sieht dich hoffnungsvoll an, {B} mit verschränkten Armen.","optionen":[{"text":"Für {B} entscheiden: Die alte Kerbe zählt.","wenn":{"flag":"kerbe"},"weiter":"ende","ergebnis":"{B} nickt zufrieden. {A} schluckt – aber gegen das alte Zeichen kann niemand etwas sagen.","folgen":{"beute":{"stufe":2,"chance":0.7,"text":"{B} drückt dir später etwas in die Hand. „Für deinen klaren Blick.“"},"sym":{"B":5,"A":-1,"C":2},"merkt":{"B":"{held} hat gerecht entschieden – mit Beweis.","A":"{held} hat gegen mich entschieden. Aber mit Beweis."},"chronik":["brett_grenze_beweis","Ich habe den Grenzstreit zwischen {A} und {B} mit einem alten Flurmal entschieden."]}},{"text":"Für {A} entscheiden – {A} braucht das Land dringender.","weiter":"ende","ergebnis":"{A} atmet auf. {B} spuckt aus und geht.","folgen":{"beute":{"stufe":2,"chance":0.7,"text":"{A} kommt am Abend vorbei und gibt dir etwas. „Das hab ich dir versprochen, wenn du zu mir hältst.“"},"sym":{"A":6,"B":-6},"merkt":{"A":"{held} hat zu mir gehalten.","B":"{held} hat mir mein Land genommen. Das merke ich mir."},"chronik":["brett_grenze_a","Im Grenzstreit habe ich mich auf die Seite von {A} gestellt."]}},{"text":"Teilen: Jeder bekommt die Hälfte, und beide pflügen gemeinsam.","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14,"mod":{"ruhig":-2,"erinnerung":-1}},"erfolg":{"text":"Lange Stille. Dann streckt {A} die Hand aus. {B} schlägt ein – zögernd, aber ein.","folgen":{"beute":{"stufe":2,"chance":0.9,"text":"Beide legen zusammen und schenken dir etwas. „Ohne dich hätten wir uns die Köpfe eingeschlagen.“"},"sym":{"A":4,"B":4,"C":3},"merkt":{"A":"{held} hat einen Frieden gefunden, den ich nicht gesehen habe.","B":"{held} hat uns beide überredet. Klug."},"chronik":["brett_grenze_frieden","Ich habe den Grenzstreit zwischen {A} und {B} geschlichtet."]},"weiter":"ende"},"misserfolg":{"text":"„Teilen? Mit dem?“ Beide gehen im Zorn. Der Streit ist nicht vorbei.","folgen":{"sym":{"A":-2,"B":-2},"chronik":["brett_grenze_offen","Der Grenzstreit zwischen {A} und {B} schwelt weiter."]},"weiter":"ende"}}]},"ende":{"ort":"dorf","ende":true,"text":"Der Stein steht, wo er steht. Ob die Wunden heilen, wird sich zeigen."}}}},{"id":"b_fieber","titel":"Fieber im Dorf","kurz":"Das Kind von {A} glüht vor Fieber. Die Kräuter im Dorf sind aufgebraucht – im Wald wächst Weidenröschen, aber dort streunen Wölfe.","schwierigkeit":2,"rollen":{"A":"Elternteil","B":"Kundige Person"},"def":{"start":"krank","szenen":{"krank":{"ort":"dorf","text":"Im Halbdunkel der Hütte liegt ein Kind unter Fellen, das Gesicht nass vom Schweiß. {A} hält seine Hand. „{B} sagt, nur frisches Weidenröschen hilft noch.“","optionen":[{"text":"Das Kind selbst untersuchen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":12},"erfolg":{"text":"Du kühlst die Stirn mit nassen Tüchern und flößt Wasser ein. Das verschafft Zeit.","folgen":{"flag":["zeit"]},"weiter":"aufbruch"},"misserfolg":{"text":"Du weißt nicht genug darüber. Es bleibt nur der Wald.","weiter":"aufbruch"}},{"text":"„Ich hole die Kräuter.“","weiter":"aufbruch"}]},"aufbruch":{"ort":"wald","text":"Der Wald ist still und kalt. Irgendwo in den Senken soll das Weidenröschen wachsen.","reise":{"minuten":2,"weiter":"senke","begegnung":{"chance":0.5,"szenen":["woelfe"]}}},"woelfe":{"ort":"wald","gefahr":true,"text":"Zwei Wölfe treten aus dem Unterholz. Mager, hungrig, wachsam.","optionen":[{"text":"Warnschuss","tag":"[Bogen]","wenn":{"item":"bogen"},"probe":{"id":"flink","dc":10},"erfolg":{"text":"Der Pfeil fährt zwischen ihnen in den Boden. Sie fliehen.","weiter":"senke"},"misserfolg":{"text":"Daneben – einer springt dich an, bevor beide abhauen.","folgen":{"gefahr":1},"weiter":"senke"}},{"text":"Groß machen und brüllen","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Sie weichen zurück.","weiter":"senke"},"misserfolg":{"text":"Ein Biss, dann sind sie fort.","folgen":{"gefahr":1},"weiter":"senke"}},{"text":"{bb} kennt sich mit Tieren aus","tag":"[{bb}]","wenn":{"begleiter_beruf":["Jäger","Jägerin","Hirte","Falknerin"]},"weiter":"senke","ergebnis":"{bb} führt euch in weitem Bogen gegen den Wind vorbei.","folgen":{"begleiter_sym":2}}]},"senke":{"ort":"wald","text":"In einer feuchten Senke leuchten violette Blüten. Daneben: ein zweiter Strauch – größer, aber du bist nicht sicher, ob er nicht giftig ist.","optionen":[{"text":"Die Pflanzen genau bestimmen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":11},"erfolg":{"text":"Der kleine ist das Weidenröschen, der große ist Fingerhut – giftig. Gut, dass du hingesehen hast.","folgen":{"flag":["richtig"]},"weiter":"rueckweg"},"misserfolg":{"text":"Du nimmst von beiden. Sicher ist sicher.","folgen":{"flag":["beides"]},"weiter":"rueckweg"}},{"text":"Einfach den großen Strauch nehmen – mehr hilft mehr","weiter":"rueckweg","folgen":{"flag":["falsch"]}}]},"rueckweg":{"ort":"wald","text":"Mit vollen Taschen eilst du zurück.","reise":{"minuten":1,"weiter":"heilen"}},"heilen":{"ort":"dorf","text":"{B} nimmt dir die Pflanzen ab und betrachtet sie genau.","optionen":[{"text":"Abwarten","wenn":{"flag":"richtig"},"weiter":"ende_gut","ergebnis":"„Genau das“, murmelt {B} und braut einen Sud. In der Nacht sinkt das Fieber.","folgen":{"sym":{"A":8,"B":3},"merkt":{"A":"{held} hat meinem Kind das Leben gerettet.","B":"{held} kennt sich mit Kräutern aus. Das hätte ich nicht gedacht."},"chronik":["brett_fieber_gerettet","Ich habe Weidenröschen für das kranke Kind von {A} geholt. Es ist wieder gesund."]}},{"text":"Abwarten","wenn":{"flag":"beides"},"weiter":"ende_gut","ergebnis":"{B} sortiert den Fingerhut aus und schüttelt den Kopf. „Gut, dass du mir beides gebracht hast.“ Das Fieber sinkt bis zum Morgen.","folgen":{"sym":{"A":6,"B":2},"merkt":{"A":"{held} hat Kräuter für mein Kind geholt."},"chronik":["brett_fieber_gerettet","Ich habe Kräuter für das kranke Kind von {A} geholt. Es ist wieder gesund."]}},{"text":"Abwarten","wenn":{"flag":"falsch"},"weiter":"ende_knapp","ergebnis":"{B} wird bleich. „Das ist Fingerhut! Hätte ich das gekocht …“ {B} schickt dich noch einmal los, diesmal mit genauer Beschreibung. Erst im Morgengrauen sinkt das Fieber.","folgen":{"sym":{"A":2,"B":-2},"merkt":{"B":"{held} hätte beinahe Gift gebracht. Gut, dass ich nachgesehen habe."},"chronik":["brett_fieber_knapp","Ich hätte dem kranken Kind von {A} beinahe Gift gebracht. Es ging gerade noch gut."]}}]},"ende_gut":{"ort":"dorf","ende":true,"text":"Am nächsten Tag sitzt das Kind schon wieder am Feuer und fragt, wann du mal wieder Geschichten erzählst.","folgen":{"beute":{"stufe":2,"chance":1,"text":"{A} besteht darauf, dass du etwas annimmst. „Ohne dich … nimm es. Bitte.“"}}},"ende_knapp":{"ort":"dorf","ende":true,"text":"Das Kind wird gesund. Aber du wirst diese Nacht nicht so schnell vergessen."}}}},{"id":"b_hohlweg","titel":"Die Räuber vom Hohlweg","kurz":"Am Hohlweg werden Reisende überfallen. {A} hat dort Waren verloren und will, dass jemand die Räuber vertreibt – so oder so.","schwierigkeit":3,"rollen":{"A":"Geschädigte Person","B":"Wer die Gegend kennt"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} zeigt dir einen zerrissenen Beutel. „Drei Männer, vermummt. Sie haben alles genommen. Wenn das so weitergeht, kommt kein Händler mehr zu uns.“ {B} fügt leise hinzu: „Ich kenne einen Pfad oberhalb des Hohlwegs.“","optionen":[{"text":"Den oberen Pfad nehmen und die Räuber beobachten","weiter":"pfad"},{"text":"Offen den Hohlweg hinaufgehen – sollen sie nur kommen","weiter":"offen"}]},"pfad":{"ort":"wald","text":"Ihr klettert über Wurzeln und Geröll, bis ihr auf den Hohlweg hinabsehen könnt.","reise":{"minuten":2,"weiter":"lager"}},"offen":{"ort":"wald","text":"Der Hohlweg ist eng, die Böschungen hoch. Ein guter Ort für einen Hinterhalt.","reise":{"minuten":1,"weiter":"hinterhalt"}},"hinterhalt":{"ort":"wald","gefahr":true,"text":"Steine poltern. Drei Gestalten springen auf den Weg, Knüppel und ein rostiges Messer in den Händen. „Beutel her!“","optionen":[{"text":"Kämpfen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":14},"erfolg":{"text":"Du schlägst den ersten nieder, die anderen zögern. Einer lässt die Kapuze fallen – ein abgemagerter Junge.","folgen":{"flag":["gesiegt"]},"weiter":"entlarvt"},"misserfolg":{"text":"Ein Knüppel trifft dich hart. Aber dann rutscht einem die Kapuze herunter – ein Junge, kaum älter als fünfzehn.","folgen":{"gefahr":2},"weiter":"entlarvt"}},{"text":"Die Waffe ziehen und drohen","tag":"[Einschüchtern]","wenn":{"item_eines":["schwert","axt","dolch","saebel","speer"]},"probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Stahl blitzt. Die drei weichen zurück, einer stolpert und verliert die Kapuze – ein Junge.","weiter":"entlarvt"},"misserfolg":{"text":"Sie greifen trotzdem an.","folgen":{"gefahr":2},"weiter":"entlarvt"}},{"text":"„Wartet. Warum tut ihr das?“","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":13},"erfolg":{"text":"Du siehst die zitternden Hände, die eingefallenen Wangen. Das sind keine Räuber. Das sind Hungrige.","folgen":{"flag":["verstanden"]},"weiter":"entlarvt"},"misserfolg":{"text":"Die Antwort ist ein Knüppelhieb.","folgen":{"gefahr":2},"weiter":"entlarvt"}}]},"lager":{"ort":"wald","text":"Unter euch, in einer Felsnische: ein armseliges Lager. Drei Männer – nein, zwei Männer und ein Junge – teilen sich einen dürren Hasen. Neben ihnen liegen {A}s Waren, unberührt.","optionen":[{"text":"Lauschen","tag":"[Schleichen]","probe":{"id":"flink","dc":12},"erfolg":{"text":"„Die Waren tauschen wir in Salzwacht gegen Korn. Dann gehen wir heim nach Erzklamm. Seit die Mine eingestürzt ist …“","folgen":{"flag":["verstanden","unentdeckt"]},"weiter":"entscheidung"},"misserfolg":{"text":"Ein Stein löst sich. Die drei springen auf.","weiter":"hinterhalt"}},{"text":"Ein Seil spannen und eine Falle am Ausgang der Nische stellen","tag":"[Anpacken]","wenn":{"item":"seil"},"probe":{"id":"anpacken","dc":11},"erfolg":{"text":"Die Falle sitzt. Wenn sie fliehen wollen, gehen sie zu Boden.","folgen":{"flag":["falle"]},"weiter":"entscheidung"},"misserfolg":{"text":"Das Seil verheddert sich.","weiter":"entscheidung"}},{"text":"Hinuntersteigen und sie stellen","weiter":"entscheidung"}]},"entlarvt":{"ort":"wald","text":"Der Älteste hebt die Hände. „Wir sind aus Erzklamm. Die Mine ist eingestürzt, es gibt kein Brot mehr. Wir wollten niemandem wehtun.“","optionen":[{"text":"Weiter","weiter":"entscheidung"}]},"entscheidung":{"ort":"wald","text":"Die Räuber sind in deiner Hand. {A}s Waren liegen da. Was jetzt?","optionen":[{"text":"Die Waren nehmen und sie laufen lassen","weiter":"ende","ergebnis":"Sie verschwinden zwischen den Bäumen. Einer dreht sich noch einmal um und nickt dir zu.","folgen":{"beute":{"stufe":3,"chance":0.8,"text":"Am Wegrand, wo sie gelagert haben, liegt etwas zurückgelassen – vielleicht absichtlich, als Dank."},"sym":{"A":4},"merkt":{"A":"{held} hat meine Waren zurückgebracht. Die Räuber sind fort."},"chronik":["brett_hohlweg_frei","Ich habe die Räuber vom Hohlweg laufen lassen – hungrige Leute aus Erzklamm."]}},{"text":"Sie gefangen nehmen und ins Dorf bringen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":12,"mod":{"falle":-4,"gesiegt":-2}},"erfolg":{"text":"Gefesselt führst du sie ins Dorf. {A} ist zufrieden. Was mit ihnen geschieht, entscheidet die Versammlung.","folgen":{"beute":{"stufe":3,"chance":1,"text":"{A} gibt dir als Belohnung etwas aus der zurückgewonnenen Ware."},"sym":{"A":6,"B":1},"merkt":{"A":"{held} hat die Räuber gefangen. Endlich Ruhe."},"chronik":["brett_hohlweg_gefangen","Ich habe die Räuber vom Hohlweg gefangen ins Dorf gebracht."]},"weiter":"ende"},"misserfolg":{"text":"Zwei entkommen, nur der Junge bleibt zurück. Er weint.","folgen":{"sym":{"A":3},"chronik":["brett_hohlweg_junge","Am Hohlweg habe ich einen jungen Räuber aus Erzklamm gefangen. Die anderen sind entkommen."]},"weiter":"ende"}},{"text":"„Kommt mit ins Dorf. Arbeit gegen Brot – das ist besser als der Hohlweg.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14,"mod":{"verstanden":-3}},"erfolg":{"text":"Lange Stille. Dann nickt der Älteste. „Wenn ihr uns nehmt, arbeiten wir.“ {A} ist skeptisch, aber die Waren sind zurück.","folgen":{"beute":{"stufe":3,"chance":1,"text":"Der Älteste gibt dir das Einzige, was er von zu Hause mitgenommen hat. „Damit du weißt, dass wir es ernst meinen.“"},"sym":{"A":2,"B":4},"merkt":{"A":"{held} hat die Räuber ins Dorf geholt. Ich traue ihnen nicht. Aber meine Waren sind zurück.","B":"{held} hat aus Räubern Arbeiter gemacht. Mutig."},"chronik":["brett_hohlweg_arbeit","Ich habe den Räubern vom Hohlweg Arbeit im Dorf angeboten. Sie kamen mit."],"journal":["erzklamm_fluechtlinge","Leute aus Erzklamm","Drei Männer aus Erzklamm arbeiten jetzt im Dorf. In Erzklamm herrscht Hunger, seit die Mine eingestürzt ist."]},"weiter":"ende"},"misserfolg":{"text":"„Damit ihr uns dann aufknüpft? Nein.“ Sie lassen die Waren fallen und fliehen.","folgen":{"sym":{"A":3}},"weiter":"ende"}}]},"ende":{"ort":"dorf","ende":true,"text":"Der Hohlweg ist wieder frei. Doch Erzklamm hungert, und das wird nicht die letzte Geschichte sein."}}}},{"id":"b_brand","titel":"Feuer in der Nacht","kurz":"Mitten in der Nacht brennt die Scheune von {A}. Jemand behauptet, {B} sei kurz vorher dort gewesen.","schwierigkeit":3,"rollen":{"A":"Geschädigte Person","B":"Beschuldigte Person","C":"Wer etwas gesehen hat"},"def":{"start":"feuer","szenen":{"feuer":{"ort":"dorf","gefahr":true,"text":"Rufe reißen dich aus dem Schlaf. Flammen schlagen aus dem Dach der Scheune von {A}. Drinnen brüllt das Vieh.","optionen":[{"text":"Hineinlaufen und das Vieh befreien","tag":"[Flink]","probe":{"id":"flink","dc":13},"erfolg":{"text":"Du reißt das Tor auf, die Tiere stürmen hinaus. Hinter dir kracht ein Balken.","folgen":{"flag":["vieh"],"sym":{"A":4}},"weiter":"loeschen"},"misserfolg":{"text":"Rauch, Hitze, ein brennender Balken streift dich. Aber die Tiere sind draußen.","folgen":{"flag":["vieh"],"sym":{"A":4},"gefahr":2},"weiter":"loeschen"}},{"text":"Eine Eimerkette organisieren","tag":"[Überreden]","probe":{"id":"ueberreden","dc":11},"erfolg":{"text":"Auf dein Kommando reihen sich alle auf. Eimer um Eimer fliegt ins Feuer.","folgen":{"flag":["kette"]},"weiter":"loeschen"},"misserfolg":{"text":"Alle laufen durcheinander.","weiter":"loeschen"}}]},"loeschen":{"ort":"dorf","text":"Im Morgengrauen ist das Feuer aus. Die Scheune ist eine schwarze Ruine. {C} zieht dich beiseite: „Ich hab {B} gestern Abend dort gesehen. Mit einer Laterne.“","optionen":[{"text":"Die Brandstelle untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":14},"erfolg":{"text":"Das Feuer begann nicht am Tor, wo {B} gestanden haben soll, sondern hinten, bei der Heuluke. Dort liegt eine umgekippte Öllampe – die von {A} selbst.","folgen":{"flag":["unfall"]},"weiter":"anklage"},"misserfolg":{"text":"Asche und Ruß. Nichts, was eindeutig wäre.","weiter":"anklage"}},{"text":"{C} genauer befragen","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":13},"erfolg":{"text":"{C} weicht deinem Blick aus. Zwischen {C} und {B} gibt es alten Streit – um ein Mädchen, vor Jahren.","folgen":{"flag":["groll"]},"weiter":"anklage"},"misserfolg":{"text":"{C} klingt sicher.","weiter":"anklage"}}]},"anklage":{"ort":"dorf","text":"Das halbe Dorf steht vor der Ruine. {A} zeigt auf {B}. „Warst du es?“ {B} schüttelt stumm den Kopf. Alle sehen dich an.","optionen":[{"text":"„Es war ein Unfall. Die Lampe von {A} lag an der Heuluke.“","wenn":{"flag":"unfall"},"weiter":"ende","ergebnis":"Ein Raunen. {A} wird rot und senkt den Kopf. {B} sieht dich an, als hättest du gerade ein Leben gerettet – und vielleicht hast du das.","folgen":{"beute":{"stufe":3,"chance":1,"text":"Am nächsten Morgen drückt dir {B} ein Erbstück in die Hand. „Du hast mir mehr gerettet als meinen Ruf.“"},"sym":{"B":8,"A":1,"C":-3},"merkt":{"B":"{held} hat bewiesen, dass ich es nicht war. Ich stehe in dieser Schuld.","C":"{held} hat mich vor allen bloßgestellt."},"chronik":["brett_brand_unfall","Ich habe bewiesen, dass der Brand bei {A} ein Unfall war – und {B} vor einer falschen Anklage bewahrt."]}},{"text":"„{C} hat einen alten Groll gegen {B}. Ich glaube {C} nicht.“","wenn":{"flag":"groll"},"weiter":"ende","ergebnis":"{C} läuft rot an und geht. Der Verdacht gegen {B} bleibt im Raum – aber er wackelt.","folgen":{"sym":{"B":4,"C":-5},"merkt":{"C":"{held} hat mich vor allen einen Lügner genannt.","B":"{held} hat zu mir gehalten."},"chronik":["brett_brand_groll","Beim Brand bei {A} habe ich die Aussage von {C} angezweifelt."]}},{"text":"„Ich weiß es nicht. Aber ohne Beweis wird niemand verurteilt.“","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":13},"erfolg":{"text":"Die Menge murrt, aber sie zerstreut sich. Niemand wird heute bestraft.","folgen":{"sym":{"B":3}},"weiter":"ende"},"misserfolg":{"text":"„Wer soll es sonst gewesen sein?“ {B} muss das Dorf für eine Weile meiden.","folgen":{"sym":{"B":-2,"A":2},"chronik":["brett_brand_verdacht","Nach dem Brand bei {A} fällt ein Schatten auf {B}."]},"weiter":"ende"}},{"text":"{B} beschuldigen","weiter":"ende","ergebnis":"{B} sieht dich an, als hättest du zugeschlagen. Dann geht {B}, ohne ein Wort.","folgen":{"sym":{"A":4,"B":-10,"C":3},"merkt":{"B":"{held} hat mich verurteilt, ohne Beweis. Das verzeihe ich nicht.","A":"{held} hat mir geholfen, den Schuldigen zu finden."},"chronik":["brett_brand_schuld","Ich habe {B} für den Brand bei {A} verantwortlich gemacht."]}}]},"ende":{"ort":"dorf","ende":true,"text":"Die Scheune muss neu gebaut werden. Und was in dieser Nacht gesagt wurde, bleibt."}}}}]$q$::jsonb) e
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, kurz = excluded.kurz, art = excluded.art, schwierigkeit = excluded.schwierigkeit, rollen = excluded.rollen, def = excluded.def;

insert into public.quest_templates (id, titel, beschreibung, art, def) values ('ki_anreise', 'Eigenes Abenteuer', 'Rahmen für KI-Abenteuer', 'system', $q${"start": "anreise", "szenen": {"anreise": {"ort": "wald", "text": "Du brichst auf, {mit}. Dein Ziel: {ziel}. Unterwegs gehst du in Gedanken durch, was dich erwarten könnte.", "reise": {"minuten": 2, "weiter": "__ki_start"}}, "__ki_start": {"ort": "wald", "text": "Der Weg zieht sich. Noch ist nicht klar, wohin er dich führt …", "optionen": [{"text": "Weitergehen", "weiter": "__ki_start"}]}}}$q$::jsonb)
on conflict (id) do update set def = excluded.def, art = excluded.art;

-- Eigenes Abenteuer beginnen: Anreise läuft sofort, die Edge-Funktion schreibt währenddessen die Geschichte
create or replace function public.quest_custom_start(p_ziel text, p_begleiter bigint[]) returns json language plpgsql security definer set search_path = public as $$
declare d date := berlin_day(); o quest_offers; v villages; rid bigint; nein text; st record; z text := left(trim(coalesce(p_ziel, '')), 200);
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  if length(z) < 8 then return json_build_object('ok', false, 'grund', 'Beschreib dein Ziel in ein paar Worten.'); end if;
  perform ensure_starter_items(auth.uid());
  if exists (select 1 from quest_runs where player_id = auth.uid() and status = 'laeuft') then return json_build_object('ok', false, 'grund', 'Du bist schon unterwegs.'); end if;
  select * into st from ai_state where id = 1;
  if st.blocked_until is not null and st.blocked_until > now() then return json_build_object('ok', false, 'grund', 'Die Erzählerin ruht gerade (KI-Kontingent erschöpft). Versuch es später wieder.'); end if;
  select * into o from quest_offers where player_id = auth.uid() and tag = d and slot = 'individuell';
  if found and o.status <> 'fehlgeschlagen' then return json_build_object('ok', false, 'grund', 'Heute hast du schon ein eigenes Abenteuer. Morgen kannst du ein neues Ziel setzen.'); end if;
  select * into v from villages where owner_id = auth.uid();
  p_begleiter := coalesce(p_begleiter, '{}');
  if array_length(p_begleiter, 1) > 2 then raise exception 'Höchstens zwei Begleiter'; end if;
  if exists (select 1 from unnest(p_begleiter) b left join npcs n on n.id = b where n.id is null or n.village_id is distinct from v.id) then raise exception 'Begleiter müssen in deinem Dorf leben'; end if;
  select string_agg(n.name, ', ') into nein from npcs n left join npc_relations r on r.npc_id = n.id and r.player_id = auth.uid() where n.id = any(p_begleiter) and coalesce(r.sympathy, 0) < 0;
  if nein is not null then return json_build_object('ok', false, 'grund', 'Nicht bereit, mit dir zu gehen: ' || nein); end if;
  insert into quest_offers (player_id, tag, slot, ziel, status) values (auth.uid(), d, 'individuell', z, 'wird_geschrieben')
    on conflict (player_id, tag, slot) do update set ziel = excluded.ziel, status = 'wird_geschrieben', template_id = null, run_id = null
    returning * into o;
  insert into quest_runs (player_id, quest_id, szene, begleiter, rollen, angebot_id) values (auth.uid(), 'ki_anreise', 'anreise', p_begleiter, jsonb_build_object('ziel', jsonb_build_object('name', z)), o.id) returning id into rid;
  perform q_enter(rid, 'anreise');
  update quest_offers set run_id = rid where id = o.id;
  return json_build_object('ok', true, 'view', quest_view(rid));
end;
$$;
revoke execute on function public.quest_custom_start(text, bigint[]) from public, anon; grant execute on function public.quest_custom_start(text, bigint[]) to authenticated;

-- Alles, was die Erzählerin wissen darf (nur für die Edge-Funktion)
create or replace function public.quest_custom_context(p_token text, p_run bigint) returns json language plpgsql stable security definer set search_path = public as $$
declare r quest_runs; me record; v villages;
begin
  if not fn_token_ok(p_token) then raise exception 'Nicht erlaubt'; end if;
  select * into r from quest_runs where id = p_run and player_id = auth.uid() and status = 'laeuft' and quest_id = 'ki_anreise';
  if not found then raise exception 'Kein wartendes Abenteuer'; end if;
  select character_name, race, coalesce(herkunft, 'waldlaeufer') herkunft into me from profiles where id = auth.uid();
  select * into v from villages where owner_id = auth.uid();
  return json_build_object(
    'ziel', r.rollen->'ziel'->>'name',
    'held', json_build_object('name', me.character_name, 'volk', me.race, 'herkunft', me.herkunft, 'eigenschaften', char_attrs(me.race, me.herkunft)),
    'dorf', v.name,
    'begleiter', (select coalesce(json_agg(json_build_object('name', n.name, 'beruf', n.job)), '[]'::json) from npcs n where n.id = any(r.begleiter)),
    'bewohner', (select coalesce(json_agg(json_build_object('id', n.id, 'name', n.name, 'beruf', n.job, 'stimmung_zum_helden', npc_stimmung(coalesce(rel.sympathy, 0)),
        'ziel', pr.ziel, 'angst', pr.angst, 'eigenart', pr.eigenart, 'staerken', pr.staerken, 'schwaechen', pr.schwaechen)), '[]'::json)
      from npcs n left join npc_profiles pr on pr.npc_id = n.id left join npc_relations rel on rel.npc_id = n.id and rel.player_id = auth.uid()
      where n.village_id = v.id and not (n.id = any(r.begleiter))),
    'chronik', (select coalesce(json_agg(c.text), '[]'::json) from (select text from chronicle where player_id = auth.uid() order by created_at desc limit 10) c),
    'tagebuch', (select coalesce(json_agg(j.title), '[]'::json) from (select title from player_journal where player_id = auth.uid() order by created_at desc limit 12) j),
    'ausruestung', (select coalesce(json_agg(distinct e.basis), '[]'::json) from p_equipment(auth.uid()) e)
  );
end;
$$;
revoke execute on function public.quest_custom_context(text, bigint) from public, anon; grant execute on function public.quest_custom_context(text, bigint) to authenticated;

-- Geprüfte Geschichte einbauen (nur Edge-Funktion)
create or replace function public.quest_custom_install(p_token text, p_run bigint, p_titel text, p_def jsonb, p_rollen jsonb, p_rollen_namen jsonb) returns json language plpgsql security definer set search_path = public as $$
declare r quest_runs; tid text; v villages; k text; val jsonb; rol jsonb := '{}'::jsonb;
begin
  if not fn_token_ok(p_token) then raise exception 'Nicht erlaubt'; end if;
  select * into r from quest_runs where id = p_run and player_id = auth.uid() and status = 'laeuft' and quest_id = 'ki_anreise' for update;
  if not found then raise exception 'Kein wartendes Abenteuer'; end if;
  select * into v from villages where owner_id = auth.uid();
  for k, val in select * from jsonb_each(coalesce(p_rollen, '{}'::jsonb)) loop
    if k in ('A','B','C') then
      select rol || jsonb_build_object(k, jsonb_build_object('id', n.id, 'name', n.name, 'beruf', n.job)) into rol from npcs n where n.id = (val #>> '{}')::bigint and n.village_id = v.id;
    end if;
  end loop;
  tid := 'ki_' || r.angebot_id;
  insert into quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def)
  values (tid, left(coalesce(p_titel, 'Eigenes Abenteuer'), 80), r.rollen->'ziel'->>'name', r.rollen->'ziel'->>'name', 'ki', 2, coalesce(p_rollen_namen, '{}'::jsonb), p_def)
  on conflict (id) do update set titel = excluded.titel, def = excluded.def, rollen = excluded.rollen;
  update quest_runs set quest_id = tid, rollen = rol || jsonb_build_object('ziel', r.rollen->'ziel') where id = r.id;
  update quest_offers set template_id = tid, status = 'angenommen' where id = r.angebot_id;
  return json_build_object('ok', true, 'template', tid);
end;
$$;
revoke execute on function public.quest_custom_install(text, bigint, text, jsonb, jsonb, jsonb) from public, anon; grant execute on function public.quest_custom_install(text, bigint, text, jsonb, jsonb, jsonb) to authenticated;

-- Schreiben gescheitert: eine Brett-Geschichte springt ein, das eigene Abenteuer darf erneut versucht werden
create or replace function public.quest_custom_fail(p_token text, p_run bigint) returns json language plpgsql security definer set search_path = public as $$
declare r quest_runs; t quest_templates; rol jsonb;
begin
  if not fn_token_ok(p_token) then raise exception 'Nicht erlaubt'; end if;
  select * into r from quest_runs where id = p_run and player_id = auth.uid() and status = 'laeuft' and quest_id = 'ki_anreise' for update;
  if not found then return json_build_object('ok', false); end if;
  for t in select * from quest_templates where art = 'brett' and schwierigkeit = 2 order by random() loop
    rol := q_cast(auth.uid(), t.rollen); exit when rol is not null;
  end loop;
  update quest_runs set quest_id = t.id, rollen = rol || jsonb_build_object('ziel', r.rollen->'ziel'), szene = t.def->>'start', warte_bis = null,
    letztes = jsonb_build_object('text', 'Die Geschichte, die du dir vorgenommen hast, will sich heute nicht fügen. Doch unterwegs kommt etwas anderes dazwischen …')
  where id = r.id;
  update quest_offers set status = 'fehlgeschlagen', run_id = null where id = r.angebot_id;
  return json_build_object('ok', true, 'ersatz', t.titel);
end;
$$;
revoke execute on function public.quest_custom_fail(text, bigint) from public, anon; grant execute on function public.quest_custom_fail(text, bigint) to authenticated;

-- Geschichten-Liste nur mit Hauptgeschichten (Brett- und KI-Vorlagen erscheinen dort nicht)
create or replace function public.quest_list() returns json language plpgsql stable security definer set search_path = public as $$
declare v villages;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into v from villages where owner_id = auth.uid();
  return json_build_object(
    'laufend', (select json_build_object('run', q.id, 'quest', q.quest_id, 'titel', t.titel) from quest_runs q join quest_templates t on t.id = q.quest_id where q.player_id = auth.uid() and q.status = 'laeuft' order by q.id desc limit 1),
    'quests', (select coalesce(json_agg(json_build_object('id', t.id, 'titel', t.titel, 'beschreibung', t.beschreibung,
        'offen', not (t.voraussetzung ? 'wissen') or exists (select 1 from player_journal j where j.player_id = auth.uid() and j.key = t.voraussetzung->>'wissen'),
        'erledigt', exists (select 1 from quest_runs q where q.player_id = auth.uid() and q.quest_id = t.id and q.status = 'fertig'),
        'hinweis', (select string_agg(n.name, ', ') from npcs n join npc_profiles p on p.npc_id = n.id where n.village_id = v.id and (t.voraussetzung->>'wissen') = any(p.wissen)))), '[]'::json) from quest_templates t where t.art = 'haupt'),
    'begleiter', (select coalesce(json_agg(json_build_object('id', n.id, 'name', n.name, 'beruf', n.job, 'bereit', coalesce(r.sympathy, 0) >= 0, 'stimmung', npc_stimmung(coalesce(r.sympathy, 0))) order by n.name), '[]'::json)
       from npcs n left join npc_relations r on r.npc_id = n.id and r.player_id = auth.uid() where n.village_id = v.id)
  );
end;
$$;
revoke execute on function public.quest_list() from public, anon; grant execute on function public.quest_list() to authenticated;
